/* ===== Tag management ===== */

static void ensure_tag_capacity(void) {
    if (tag_count >= tag_capacity) {
        tag_capacity = tag_capacity ? tag_capacity * 2 : 65536;
        tags = realloc(tags, tag_capacity * sizeof(Tag));
        if (!tags) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
    }
}

static void add_tag(const char *name, const char *file, int line_num,
                    const char *pattern, char kind, const char *kind_name,
                    const char *scope, const char *scope_kind, const char *scope_kind_name,
                    const char *typeref, int file_scope, LangID lang) {
    if (!name || !*name) return;

    ensure_tag_capacity();
    Tag *t = &tags[tag_count];
    memset(t, 0, sizeof(Tag));

    strncpy(t->name, name, MAX_NAME_LEN - 1);
    strncpy(t->file, file, MAX_PATH_LEN - 1);
    t->line_num = line_num;

    if (pattern) {
        /* Truncate pattern to limit */
        int plen = pattern_length_limit > 0 ? pattern_length_limit : (int)strlen(pattern);
        strncpy(t->pattern, pattern, plen < MAX_LINE_LEN - 1 ? plen : MAX_LINE_LEN - 1);
    }

    t->kind = kind;
    if (kind_name) strncpy(t->kind_name, kind_name, 63);
    if (scope) strncpy(t->scope, scope, MAX_NAME_LEN - 1);
    if (scope_kind) strncpy(t->scope_kind, scope_kind, 63);
    if (scope_kind_name) strncpy(t->scope_kind_name, scope_kind_name, 63);
    if (typeref) strncpy(t->typeref, typeref, MAX_NAME_LEN - 1);
    t->file_scope = file_scope;
    t->lang = lang;

    tag_count++;
    total_tags++;
}

/* ===== Comparison for sorting ===== */

static int tag_cmp(const void *a, const void *b) {
    const Tag *ta = (const Tag *)a;
    const Tag *tb = (const Tag *)b;

    int cmp;
    if (sort_tags == 2) {
        /* foldcase */
        cmp = strcasecmp(ta->name, tb->name);
        if (cmp == 0) cmp = strcmp(ta->name, tb->name);
    } else {
        cmp = strcmp(ta->name, tb->name);
    }

    if (cmp == 0) {
        cmp = strcmp(ta->file, tb->file);
    }
    if (cmp == 0) {
        cmp = ta->line_num - tb->line_num;
    }
    return cmp;
}

/* ===== Pattern escaping ===== */

static char *escape_pattern(const char *s, char *buf, int bufsize) {
    int j = 0;
    for (int i = 0; s[i] && j < bufsize - 2; i++) {
        if (s[i] == '\\') {
            buf[j++] = '\\';
            buf[j++] = '\\';
        } else {
            buf[j++] = s[i];
        }
    }
    buf[j] = '\0';
    return buf;
}

/* ===== Tag output ===== */

static void print_tag_ctags(FILE *fp, const Tag *t) {
    char escaped[MAX_LINE_LEN * 2];

    if (output_format == 4) {
        /* JSON format */
        fprintf(fp, "{\"_type\": \"tag\", \"name\": \"%s\", \"path\": \"%s\"", t->name, t->file);

        if (excmd_mode == 1 || (excmd_mode == 0 && t->line_num > 0 && !t->pattern[0])) {
            fprintf(fp, ", \"line\": %d", t->line_num);
        } else if (t->pattern[0]) {
            escape_pattern(t->pattern, escaped, sizeof(escaped));
            if (backwards_search)
                fprintf(fp, ", \"pattern\": \"?^%s$?\"", escaped);
            else
                fprintf(fp, ", \"pattern\": \"/^%s$/\"", escaped);
        } else {
            fprintf(fp, ", \"line\": %d", t->line_num);
        }

        if (t->file_scope) fprintf(fp, ", \"file\": true");

        if (t->scope[0] && t->scope_kind[0]) {
            /* In JSON output: scope name and kind shown separately */
            fprintf(fp, ", \"%s\": \"%s\"", t->scope_kind, t->scope);
        }

        if (t->typeref[0]) {
            fprintf(fp, ", \"typeref\": \"%s\"", t->typeref);
        }

        if (field_line) fprintf(fp, ", \"line\": %d", t->line_num);
        if (field_language) {
            /* Map lang ID to language name */
        }

        fprintf(fp, ", \"kind\": \"%s\"", t->kind_name[0] ? t->kind_name : "unknown");

        if (t->scope[0] && t->scope_kind_name[0]) {
            fprintf(fp, ", \"scope\": \"%s\"", t->scope);
            fprintf(fp, ", \"scopeKind\": \"%s\"", t->scope_kind_name);
        }

        fprintf(fp, "}\n");
        return;
    }

    if (output_format == 3) {
        /* xref format */
        char kind_word[64] = "unknown";
        if (t->kind_name[0]) strncpy(kind_word, t->kind_name, 63);
        fprintf(fp, "%-16s %-12s %4d %-20s %s\n",
                t->name, kind_word, t->line_num, t->file, t->pattern);
        return;
    }

    if (output_format == 2) {
        /* etags format - different entirely */
        return;
    }

    /* u-ctags and e-ctags format */
    fprintf(fp, "%s\t%s\t", t->name, t->file);

    if (excmd_mode == 1) {
        /* line number */
        fprintf(fp, "%d;\"", t->line_num);
    } else if (excmd_mode == 2) {
        /* pattern only */
        escape_pattern(t->pattern, escaped, sizeof(escaped));
        if (backwards_search)
            fprintf(fp, "?^%s$?\";\"", escaped);
        else
            fprintf(fp, "/^%s$/;\"", escaped);
    } else {
        /* mix mode (default) */
        if (t->pattern[0]) {
            escape_pattern(t->pattern, escaped, sizeof(escaped));
            if (backwards_search)
                fprintf(fp, "?^%s$?;\"", escaped);
            else
                fprintf(fp, "/^%s$/;\"", escaped);
        } else {
            fprintf(fp, "%d;\"", t->line_num);
        }
    }

    /* Kind */
    fprintf(fp, "\t%c", t->kind);

    /* Extension fields */
    if (field_line) fprintf(fp, "\tline:%d", t->line_num);
    if (field_language) {
        /* print language name */
        const char *lname = "C";
        switch (t->lang) {
            case LANG_C: lname = "C"; break;
            case LANG_CPP: lname = "C++"; break;
            case LANG_PYTHON: lname = "Python"; break;
            case LANG_JAVASCRIPT: lname = "JavaScript"; break;
            case LANG_TYPESCRIPT: lname = "TypeScript"; break;
            case LANG_JAVA: lname = "Java"; break;
            case LANG_GO: lname = "Go"; break;
            case LANG_RUBY: lname = "Ruby"; break;
            case LANG_RUST: lname = "Rust"; break;
            case LANG_PHP: lname = "PHP"; break;
            case LANG_PERL: lname = "Perl"; break;
            case LANG_SH: lname = "Sh"; break;
