            case LANG_KOTLIN: lname = "Kotlin"; break;
            case LANG_SCALA: lname = "Scala"; break;
            case LANG_CSHARP: lname = "C#"; break;
            case LANG_PROTOBUF: lname = "Protobuf"; break;
            case LANG_FORTRAN: lname = "Fortran"; break;
            case LANG_TCL: lname = "Tcl"; break;
            case LANG_SCHEME: lname = "Scheme"; break;
            case LANG_LISP: lname = "Lisp"; break;
            case LANG_CLOJURE: lname = "Clojure"; break;
            case LANG_ERLANG: lname = "Erlang"; break;
