            case LANG_THRIFT: lname = "Thrift"; break;
            default: lname = "Unknown"; break;
        }
        fprintf(fp, "\tlanguage:%s", lname);
    }

    if (t->scope[0] && t->scope_kind[0]) {
        fprintf(fp, "\t%s:%s", t->scope_kind, t->scope);
    }

    if (t->typeref[0]) {
