    if (t->signature[0]) fprintf(fp, "\tsignature:%s", t->signature);
    if (t->inherits[0]) fprintf(fp, "\tinherits:%s", t->inherits);
    if (t->end_line > 0) fprintf(fp, "\tend:%d", t->end_line);

    if (t->file_scope) fprintf(fp, "\tfile:");

    fprintf(fp, "\n");
}

