                    const char *pattern, char kind, const char *kind_name,
                    const char *scope, const char *scope_kind, const char *scope_kind_name,
                    const char *typeref, int file_scope, int lang);
extern int pattern_length_limit;

/* Scope tracking */
#define MAX_SCOPE_DEPTH 32

typedef struct {
    char name[MAX_NAME_LEN];
    char kind; /* c=class, s=struct, u=union, n=namespace, f=function, etc */
    char kind_name[32];
    int line;
    int is_file_scope;
} ScopeEntry;

static ScopeEntry scope_stack[MAX_SCOPE_DEPTH];
static int scope_depth = 0;

static void push_scope(const char *name, char kind, const char *kind_name, int line, int file_scope) {
    if (scope_depth < MAX_SCOPE_DEPTH) {
        strncpy(scope_stack[scope_depth].name, name, MAX_NAME_LEN-1);
        scope_stack[scope_depth].kind = kind;
        strncpy(scope_stack[scope_depth].kind_name, kind_name, 31);
        scope_stack[scope_depth].line = line;
        scope_stack[scope_depth].is_file_scope = file_scope;
        scope_depth++;
    }
}

static void pop_scope(void) {
    if (scope_depth > 0) scope_depth--;
}

static void get_scope_string(char *out, int outsize, char *kind_out, char *kind_name_out) {
    if (scope_depth == 0) {
        out[0] = '\0';
        kind_out[0] = '\0';
        kind_name_out[0] = '\0';
        return;
    }

    /* Build fully-qualified scope name */
    char tmp[MAX_NAME_LEN * MAX_SCOPE_DEPTH] = "";
    for (int i = 0; i < scope_depth; i++) {
        if (i > 0) {
            if (scope_stack[i-1].kind == 'n') {
                strncat(tmp, "::", MAX_NAME_LEN - strlen(tmp) - 1);
            } else {
                strncat(tmp, "::", MAX_NAME_LEN - strlen(tmp) - 1);
            }
        }
        strncat(tmp, scope_stack[i].name, MAX_NAME_LEN - strlen(tmp) - 1);
    }

    strncpy(out, tmp, outsize - 1);
    out[outsize-1] = '\0';

    /* Kind is the innermost scope's kind */
    kind_out[0] = scope_stack[scope_depth-1].kind;
    kind_out[1] = '\0';
    strncpy(kind_name_out, scope_stack[scope_depth-1].kind_name, 63);
}

