        "bool", "catch", "class", "constexpr", "const_cast", "delete",
        "dynamic_cast", "explicit", "export", "false", "friend",
        "mutable", "namespace", "new", "noexcept", "nullptr", "operator",
        "override", "private", "protected", "public", "reinterpret_cast",
        "static_assert", "static_cast", "template", "this", "throw",
        "true", "try", "typeid", "typename", "using", "virtual",
        "wchar_t", "final", "override", "nullptr", "alignas", "alignof",
        "thread_local", "decltype", "static_assert",
        NULL
    };
    for (int i = 0; kw[i]; i++) {
        if (strcmp(w, kw[i]) == 0) return 1;
    }
    return 0;
}

/* Parse a pattern line - trim to limit */
static void make_pattern(const char *line, char *out, int outsize) {
    int limit = pattern_length_limit > 0 ? pattern_length_limit : (int)strlen(line);
    if (limit > outsize - 1) limit = outsize - 1;

    /* Copy trimmed from right */
    int len = strlen(line);
    while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) len--;
    if (len > limit) len = limit;
    memcpy(out, line, len);
    out[len] = '\0';
}

/* Generate an anonymous tag name based on line number hash */
