    /* Universal Ctags uses a hash-based naming for anonymous structs */
    /* Format: __anonXXXXXXXXYYYY where X is based on filename and Y is line */
    unsigned int h = 5381;
    for (const char *p = filename; *p; p++) {
        h = ((h << 5) + h) ^ (unsigned char)*p;
    }
    sprintf(out, "__anon%08x%04d", h, line);
