    FILE *fp = fopen(filename, "r");
    if (!fp) return 0;

    cstate.num_lines = 0;
    while (cstate.num_lines < 100000) {
        if (!fgets(cstate.lines[cstate.num_lines], MAX_LINE_LEN, fp)) break;
        /* Remove newline */
        int len = strlen(cstate.lines[cstate.num_lines]);
        while (len > 0 && (cstate.lines[cstate.num_lines][len-1] == '\n' || 
                           cstate.lines[cstate.num_lines][len-1] == '\r')) {
            cstate.lines[cstate.num_lines][--len] = '\0';
        }
        cstate.num_lines++;
    }
    fclose(fp);
    return 1;
}

/* Skip whitespace */
static const char *skip_ws(const char *p) {
    while (*p && isspace((unsigned char)*p)) p++;
    return p;
}

/* Read an identifier */
static int read_ident(const char *p, char *out, int outsize) {
    if (!*p || (!isalpha((unsigned char)*p) && *p != '_')) return 0;
    int i = 0;
    while (*p && (isalnum((unsigned char)*p) || *p == '_') && i < outsize-1) {
        out[i++] = *p++;
    }
    out[i] = '\0';
    return i;
}

/* Skip balanced braces/parens, return pointer after closing */
static const char *skip_balanced(const char *p, char open, char close) {
    if (*p != open) return p;
    p++;
    int depth = 1;
    int in_str = 0, in_char = 0;
    while (*p && depth > 0) {
        if (!in_str && !in_char) {
            if (*p == '"') in_str = 1;
            else if (*p == '\'') in_char = 1;
            else if (*p == open) depth++;
            else if (*p == close) depth--;
            else if (*p == '/' && *(p+1) == '/') break; /* line comment */
        } else if (in_str) {
            if (*p == '\\') p++; /* skip escaped char */
            else if (*p == '"') in_str = 0;
        } else if (in_char) {
            if (*p == '\\') p++; /* skip escaped char */
            else if (*p == '\'') in_char = 0;
        }
        if (*p) p++;
    }
    return p;
}

