# ===== Language detection =====

def detect_language(filename, force_lang=None):
    """Detect the language of a file based on extension/pattern."""
    if force_lang and force_lang != 'auto':
        return force_lang

    base = os.path.basename(filename)

    # Check by full filename patterns first
    for name, lang in LANGUAGES.items():
        if lang['disabled']:
            continue
        for pat in lang['patterns']:
            try:
                if fnmatch.fnmatch(base, pat):
                    return name
            except:
                pass

    # Check by extension
    dot = base.rfind('.')
    if dot >= 0:
        ext = base[dot+1:]
        # Special: .h files - check context (default to C)
        for name, lang in LANGUAGES.items():
            if lang['disabled']:
                continue
            if ext in lang['extensions']:
                return name

    return None

def detect_language_from_shebang(filename):
    """Try to detect language from shebang line."""
    try:
        with open(filename, 'r', errors='replace') as f:
            first_line = f.readline().strip()
    except:
        return None

    if first_line.startswith('#!'):
        shebang = first_line[2:].strip()
        # Extract interpreter name
        parts = shebang.split()
        if parts:
            interp = os.path.basename(parts[0])
            if interp == 'env' and len(parts) > 1:
                interp = os.path.basename(parts[1])

            interp_lower = interp.lower()
            if 'python' in interp_lower:
                return 'Python'
            elif 'ruby' in interp_lower:
                return 'Ruby'
            elif 'perl' in interp_lower:
                return 'Perl'
            elif interp in ('sh', 'bash', 'ksh', 'ash', 'dash'):
                return 'Sh'
            elif interp == 'zsh':
                return 'Zsh'
