# ===== Main processing =====

def process_files(input_files, output_file=None, write_stdout=False):
    """Process a list of input files and write tags."""
    all_tags = []
    used_langs = set()

    for filename in input_files:
        # Detect language
        if opts.force_language:
            lang = opts.force_language
        else:
            lang = detect_language(filename, opts.force_language)
            if lang is None and opts.guess_eagerly:
                lang = detect_language_from_shebang(filename)

        if lang is None:
            continue

        # Check if language is enabled
        if opts.languages_include is not None:
            if lang not in opts.languages_include:
                continue
        if lang in opts.languages_exclude:
            continue

        # Check if language is disabled
        if lang in LANGUAGES and LANGUAGES[lang].get('disabled'):
            continue

        # Parse file
        file_tags = []
        try:
            parse_file(filename, lang, file_tags)
        except Exception as e:
            if opts.verbose:
                print(f"Warning: error parsing {filename}: {e}", file=sys.stderr)
            continue

        if file_tags:
            used_langs.add(lang)
        all_tags.extend(file_tags)

    # Sort tags
    if opts.sort == 1:
        all_tags.sort(key=lambda t: (t.name, t.file, t.line))
    elif opts.sort == 2:
        all_tags.sort(key=lambda t: (t.name.lower(), t.name, t.file, t.line))

    # Build field options dict
    field_opts = {
        'n': opts.field_line,
        'l': opts.field_language,
        'a': opts.field_access,
        'e': opts.field_end,
        'S': opts.field_signature,
        'i': opts.field_inherits,
        'r': opts.field_roles,
        'z': opts.field_kind_flag,
        'K': opts.field_kind_long,
    }

    excmd_str = opts.excmd
    if excmd_str == 'mix':
        excmd_display = 'mixed'
    elif excmd_str == 'combine':
        excmd_display = 'combineV2'
    else:
        excmd_display = excmd_str

    sort_val = opts.sort

    # Determine output format
    fmt = opts.output_format

    # Open output
    if write_stdout or output_file == '-':
        fp = sys.stdout
        close_fp = False
    elif fmt == 'xref':
        fp = sys.stdout
        close_fp = False
    elif output_file:
        mode = 'a' if opts.append else 'w'
        try:
            fp = open(output_file, mode, encoding='utf-8', errors='replace')
        except Exception as e:
            print(f"{get_prog()}: cannot open output file: {e}", file=sys.stderr)
            return
        close_fp = True
    else:
        fp = sys.stdout
        close_fp = False

    try:
        # Write pseudo-tags header (except for stdout/xref/json output)
        if fmt not in ('xref', 'json') and (output_file and output_file != '-' and not write_stdout):
            write_pseudo_tags(fp, used_langs, fmt, excmd_display, sort_val)

        # Write tags
        for tag in all_tags:
            write_tag_line(fp, tag, fmt, opts.excmd, opts.backwards_search, field_opts)
    finally:
        if close_fp:
            fp.close()

    return all_tags, used_langs


def should_exclude(path):
    """Check if a path matches any exclude pattern."""
    basename = os.path.basename(path)
    for pat in opts.excludes:
        if fnmatch.fnmatch(basename, pat) or fnmatch.fnmatch(path, pat):
            # Check exceptions
            for exc in opts.exclude_exceptions:
                if fnmatch.fnmatch(basename, exc) or fnmatch.fnmatch(path, exc):
                    return False
            return True
    return False


def collect_files_recursive(directory, depth=0):
    """Recursively collect files from a directory."""
    if opts.max_depth >= 0 and depth > opts.max_depth:
        return []

    result = []
    try:
        entries = sorted(os.listdir(directory))
    except Exception:
        return []

    for entry in entries:
        full_path = os.path.join(directory, entry)

        if should_exclude(full_path):
            continue

        if os.path.islink(full_path) and not opts.follow_links:
            continue

        if os.path.isdir(full_path):
            result.extend(collect_files_recursive(full_path, depth + 1))
        elif os.path.isfile(full_path):
            result.append(full_path)

    return result

