# ===== Argument parsing =====

def parse_bool(s, default=True):
    if s is None or s == '':
        return default
    return s.lower() in ('yes', 'true', '1', 'on')

def parse_args(argv):
    global opts

    i = 0
    n = len(argv)

    while i < n:
        arg = argv[i]

        if arg == '--':
            opts.input_files.extend(argv[i+1:])
            break

        if not arg.startswith('-'):
            opts.input_files.append(arg)
            i += 1
            continue

        # Single letter options
        if arg.startswith('-') and not arg.startswith('--') and len(arg) > 1:
            j = 1
            while j < len(arg):
                c = arg[j]
                if c == 'R':
                    opts.recurse = True
                elif c == 'a':
                    opts.append = True
                elif c == 'e':
                    opts.output_format = 'etags'
                elif c == 'x':
                    opts.output_format = 'xref'
                elif c == 'u':
                    opts.sort = 0
                elif c == 'n':
                    opts.excmd = 'number'
                elif c == 'N':
                    opts.excmd = 'pattern'
                elif c == 'B':
                    opts.backwards_search = True
                elif c == 'F':
                    opts.backwards_search = False
                elif c == 'V':
                    opts.verbose = True
                elif c == 'G':
                    opts.guess_eagerly = True
                elif c == '?':
                    print(HELP_TEXT.format(prog=get_prog()))
                    sys.exit(0)
                elif c == 'f' or c == 'o':
                    if j + 1 < len(arg):
                        opts.output_file = arg[j+1:]
                        if opts.output_file == '-':
                            opts.write_stdout = True
                        j = len(arg) - 1
                    elif i + 1 < n:
                        i += 1
                        opts.output_file = argv[i]
                        if opts.output_file == '-':
                            opts.write_stdout = True
                elif c == 'L':
                    if j + 1 < len(arg):
                        list_file = arg[j+1:]
                        j = len(arg) - 1
                    elif i + 1 < n:
                        i += 1
                        list_file = argv[i]
                    else:
                        list_file = None
                    if list_file:
                        if list_file == '-':
                            for line in sys.stdin:
                                opts.input_files.append(line.rstrip('\n\r'))
                        else:
                            try:
                                with open(list_file) as lf:
                                    for line in lf:
                                        opts.input_files.append(line.rstrip('\n\r'))
                            except Exception as e:
                                print(f"{get_prog()}: {e}", file=sys.stderr)
                elif c == 'D':
                    # Macro definition
                    if j + 1 < len(arg):
                        defn = arg[j+1:]
                        j = len(arg) - 1
                    elif i + 1 < n:
                        i += 1
                        defn = argv[i]
                    else:
                        defn = ''
                    if '=' in defn:
                        k, v = defn.split('=', 1)
                        opts.defines[k] = v
                elif c == 'h':
                    # Include extensions
                    if j + 1 < len(arg):
                        opts.include_exts = arg[j+1:].split('.')
                        j = len(arg) - 1
                    elif i + 1 < n:
                        i += 1
                        opts.include_exts = argv[i].split('.')
                elif c == 'I':
                    # Ignore tokens
                    if j + 1 < len(arg):
                        toks = arg[j+1:]
                        j = len(arg) - 1
                    elif i + 1 < n:
                        i += 1
                        toks = argv[i]
                    else:
                        toks = ''
                    for t in toks.split():
                        opts.ignore_tokens.add(t)
                j += 1
            i += 1
            continue

        # Long options
        if '=' in arg:
            name, val = arg.split('=', 1)
        else:
            name = arg
            val = None

        if name == '--help' or name == '--help-full':
            print(HELP_TEXT.format(prog=get_prog()))
            sys.exit(0)
        elif name == '--version':
            if val:
                # Print version for specific language
                for lang_name, info in LANGUAGES.items():
                    if lang_name.lower() == val.lower():
                        print(info.get('parser_version', '0.0'))
                        sys.exit(0)
                print(f"{get_prog()}: Unknown language: {val}", file=sys.stderr)
                sys.exit(1)
            else:
                print(VERSION_STRING)
                sys.exit(0)
        elif name == '--license':
            # Print license info
            print("This software is licensed under GPL v2.")
            sys.exit(0)
        elif name == '--recurse':
            opts.recurse = parse_bool(val)
        elif name == '--append':
            opts.append = parse_bool(val)
        elif name == '--filter':
            opts.filter_mode = parse_bool(val)
        elif name == '--filter-terminator':
            opts.filter_terminator = val
        elif name == '--links':
            opts.follow_links = parse_bool(val)
        elif name == '--maxdepth':
            opts.max_depth = int(val) if val else -1
        elif name in ('-f', '-o', '--output-file'):
            opts.output_file = val or (argv[i+1] if i+1 < n else 'tags')
            if opts.output_file == '-':
                opts.write_stdout = True
        elif name == '--format':
            opts.format = int(val) if val else 2
        elif name == '--output-format':
            opts.output_format = val or 'u-ctags'
        elif name == '--sort':
            if val == 'yes':
                opts.sort = 1
            elif val == 'no':
                opts.sort = 0
            elif val == 'foldcase':
                opts.sort = 2
        elif name == '--excmd':
            opts.excmd = val or 'mix'
        elif name == '--language-force':
            if val and val != 'auto':
                opts.force_language = val
            else:
                opts.force_language = None
        elif name == '--languages':
            if val:
                # Parse +/-/language list
                if val.startswith('+'):
                    # Add to includes
                    langs = val[1:].split(',')
                    if opts.languages_include is None:
                        opts.languages_include = set()
                    for l in langs:
                        l = l.strip()
                        if l == 'all':
                            opts.languages_include = None
                        else:
                            opts.languages_include.add(l)
                            opts.languages_exclude.discard(l)
                elif val.startswith('-'):
                    # Exclude languages
                    langs = val[1:].split(',')
                    for l in langs:
                        l = l.strip()
                        if l == 'all':
                            opts.languages_exclude = set(LANGUAGES.keys())
                        else:
                            opts.languages_exclude.add(l)
                            if opts.languages_include:
                                opts.languages_include.discard(l)
                else:
                    # Set exact list
                    langs = val.split(',')
                    if 'all' in langs:
                        opts.languages_include = None
                    else:
                        opts.languages_include = set(l.strip() for l in langs)
        elif name == '--print-language':
            opts.print_language = True
        elif name == '--guess-language-eagerly':
            opts.guess_eagerly = True
        elif name == '--verbose':
            opts.verbose = parse_bool(val)
        elif name == '--quiet':
            opts.quiet = parse_bool(val)
        elif name == '--totals':
            opts.totals = True
        elif name == '--if0':
            opts.if0 = parse_bool(val)
        elif name == '--line-directives':
            opts.line_directives = parse_bool(val)
        elif name == '--tag-relative':
            opts.tag_relative = val or 'yes'
        elif name == '--backwards-search' or name == '-B':
            opts.backwards_search = True
        elif name == '--pattern-length-limit':
            opts.pattern_length_limit = int(val) if val else 96
        elif name == '--machinable':
            opts.machinable = parse_bool(val)
        elif name == '--with-list-header':
            opts.with_list_header = parse_bool(val)
        elif name == '--put-field-prefix':
            opts.put_field_prefix = True
        elif name == '--exclude':
            if val:
                opts.excludes.append(val)
        elif name == '--exclude-exception':
            if val:
                opts.exclude_exceptions.append(val)
        elif name == '--fields':
            if val:
                apply_fields_spec(val)
        elif name.startswith('--fields-'):
            pass  # Language-specific fields - ignore for now
        elif name == '--extras':
            if val:
                apply_extras_spec(val)
        elif name.startswith('--extras-'):
            pass
        elif name.startswith('--kinds-'):
            if val:
                lang_part = name[len('--kinds-'):]
                apply_kinds_spec(lang_part, val)
        elif name == '--etags-include':
            if val:
                opts.etags_includes.append(val)
        elif name == '--input-encoding':
            opts.input_encoding = val
        elif name == '--output-encoding':
            opts.output_encoding = val
        elif name.startswith('--input-encoding-'):
            pass  # Language-specific input encoding
        elif name == '--langmap':
            if val:
                parse_langmap(val)
        elif name.startswith('--map-'):
            pass
        elif name.startswith('--alias-'):
            pass
        elif name == '--options' or name == '--options-maybe':
            if val and os.path.exists(val):
                try:
                    with open(val) as optf:
                        extra_args = []
                        for line in optf:
                            line = line.strip()
                            if line and not line.startswith('#'):
                                extra_args.append(line)
                        parse_args(extra_args)
                except Exception:
                    pass
        elif name == '--optlib-dir':
            pass
        elif name.startswith('--regex-'):
            pass  # Regex-based parser definitions
        elif name.startswith('--mline-regex-'):
            pass
        elif name.startswith('--langdef'):
            pass
        elif name.startswith('--kinddef-'):
            pass
        elif name.startswith('--param-'):
            pass
        elif name.startswith('--roles-'):
            pass
        elif name == '--pseudo-tags':
            if val:
                apply_pseudo_tags(val)
        elif name == '--list-languages':
            list_languages()
            sys.exit(0)
        elif name == '--list-features':
            list_features()
            sys.exit(0)
        elif name.startswith('--list-kinds'):
            lang_arg = val if val else None
            if not lang_arg and name == '--list-kinds':
                lang_arg = 'all'
            list_kinds(lang_arg)
            sys.exit(0)
        elif name.startswith('--list-map-extensions'):
            list_map_extensions(val)
            sys.exit(0)
        elif name.startswith('--list-map-patterns'):
            list_map_patterns(val)
            sys.exit(0)
        elif name.startswith('--list-maps'):
            list_maps(val)
            sys.exit(0)
        elif name.startswith('--list-extras'):
            list_extras(val)
            sys.exit(0)
        elif name.startswith('--list-fields'):
            list_fields(val)
            sys.exit(0)
        elif name == '--list-output-formats':
            print('u-ctags  Universal ctags original format')
            print('e-ctags  Exuberant ctags format')
            print('etags    Emacs etags format')
            print('xref     Cross-reference format')
            print('json     JSON format')
            sys.exit(0)
        elif name == '--list-excludes':
            for pat in opts.excludes:
                print(pat)
            sys.exit(0)
        elif name in ('--list-aliases', '--list-roles', '--list-subparsers',
                      '--list-pseudo-tags', '--list-params', '--list-regex-flags',
                      '--list-mline-regex-flags', '--list-map-rexprs',
                      '--list-kinds-full', '--describe-language'):
            # These need more implementation, but for now print empty/basic output
            pass
        else:
            # Unknown option - print warning but continue
            if opts.verbose:
                print(f"{get_prog()}: Unknown option: {arg}", file=sys.stderr)

        i += 1


def apply_fields_spec(spec):
    """Apply a --fields specification like '+n', '-l', 'nls', etc."""
    global opts
    if spec.startswith('+'):
        enable = True
        spec = spec[1:]
    elif spec.startswith('-'):
        enable = False
        spec = spec[1:]
    else:
        # Set exactly
        # First disable all
        opts.field_line = False
        opts.field_language = False
        opts.field_access = False
        opts.field_end = False
        opts.field_signature = False
        opts.field_inherits = False
        opts.field_roles = False
        opts.field_scope_kind = False
        opts.field_kind_long = False
        opts.field_kind_flag = False
        opts.field_nth = False
        enable = True

    field_map = {
        'n': 'field_line', 'l': 'field_language', 'a': 'field_access',
        'e': 'field_end', 'S': 'field_signature', 'i': 'field_inherits',
        'r': 'field_roles', 'f': 'field_file', 'p': 'field_scope_kind',
        'K': 'field_kind_long', 'z': 'field_kind_flag', 'o': 'field_nth',
        'x': 'field_xpath', 'T': 'field_epoch', 't': 'field_typeref',
        's': None,  # scope field (enabled by default)
