def apply_fields_spec(spec):
    """Apply a --fields specification like '+n', '-l', 'nls', etc."""
    global opts
    if spec.startswith('+'):
        enable = True
        spec = spec[1:]
    elif spec.startswith('-'):
        enable = False
        spec = spec[1:]
    else:
        # Set exactly
        # First disable all
        opts.field_line = False
        opts.field_language = False
        opts.field_access = False
        opts.field_end = False
        opts.field_signature = False
        opts.field_inherits = False
        opts.field_roles = False
        opts.field_scope_kind = False
        opts.field_kind_long = False
        opts.field_kind_flag = False
        opts.field_nth = False
        enable = True

    field_map = {
        'n': 'field_line', 'l': 'field_language', 'a': 'field_access',
        'e': 'field_end', 'S': 'field_signature', 'i': 'field_inherits',
        'r': 'field_roles', 'f': 'field_file', 'p': 'field_scope_kind',
        'K': 'field_kind_long', 'z': 'field_kind_flag', 'o': 'field_nth',
        'x': 'field_xpath', 'T': 'field_epoch', 't': 'field_typeref',
        's': None,  # scope field (enabled by default)
    }

    if spec == '*':
        for attr in ['field_line', 'field_language', 'field_access', 'field_end',
                     'field_signature', 'field_inherits']:
            setattr(opts, attr, enable)
    else:
        for c in spec:
            attr = field_map.get(c)
            if attr:
                setattr(opts, attr, enable)


def apply_extras_spec(spec):
