def apply_kinds_spec(lang, spec):
    """Apply a --kinds-<LANG> specification."""
    global opts
    if spec.startswith('+'):
        enable = True
        spec = spec[1:]
    elif spec.startswith('-'):
        enable = False
        spec = spec[1:]
    else:
        enable = True

    if lang.lower() == 'all':
