    for l in langs:
        if enable:
            if l not in opts.kinds_enabled:
                opts.kinds_enabled[l] = set()
            for c in spec:
                opts.kinds_enabled[l].add(c)
            if l in opts.kinds_disabled:
                for c in spec:
                    opts.kinds_disabled[l].discard(c)
        else:
